const input = $input.first().json.body || $input.first().json;
const catalog = Array.isArray(input.catalog) ? input.catalog.slice(0, 100).map(x => ({ ref: x.ref || x.id, title: x.title, category: x.category, description: x.description, tags: x.tags, durationMinutes: Number(x.durationMinutes || 0), price: Number(x.price || 0), availableSlots: x.availableSlots, accessibility: x.accessibility })) : [];
const preferences = { interests: Array.isArray(input.interests) ? input.interests.slice(0, 20) : [], budget: input.budget == null ? null : Number(input.budget), timeWindow: input.timeWindow || null, accessibilityNeeds: Array.isArray(input.accessibilityNeeds) ? input.accessibilityNeeds : [] };
const prompt = `Recommend up to five experiences and draft a practical itinerary using only the supplied catalog and preferences. Respect stated budget, time window and accessibility needs. Do not invent availability, price, venue details, safety claims, or endorsements. Never book, charge, contact providers or expose participant details. Return JSON with recommendations [{ref,reason}], itinerary [{ref,start,end}], caveats [].
CATALOG=${JSON.stringify(catalog)}
PREFERENCES=${JSON.stringify(preferences)}`;
return [{ json: { prompt } }];

const response = $input.first().json;
let result; try { result = JSON.parse(response.candidates[0].content.parts[0].text); } catch { result = { recommendations: [], itinerary: [], caveats: ['AI response unavailable; check the catalog directly.'] }; }
return [{ json: { status: 'suggestions_ready', result, bookingCreated: false, requiresUserConfirmation: true } }];
